mapper.select:
select *
from batch.calendar_dependency_wait
where tenant_id = #{tenantId}
  and calendar_code = #{calendarCode}
  and biz_date = #{bizDate}

select count(*)
  from batch.calendar_dependency_wait
 where tenant_id = #{tenantId}
   and calendar_code = #{calendarCode}
   and biz_date = #{bizDate}
   and wait_status = 'WAITING'

select *
from batch.calendar_dependency_wait
where tenant_id = #{tenantId}
  and calendar_code = #{calendarCode}
  and wait_status = 'WAITING'
  and last_checked_at < #{checkedBefore}
order by biz_date, id
limit #{limit}
for update skip locked

select *
  from batch.calendar_dependency_wait
 where tenant_id = #{tenantId}

   and calendar_code = #{calendarCode}


   and wait_status = #{waitStatus}

 order by case when wait_status = 'WAITING' then 0 else 1 end,
          biz_date desc, id desc
 limit #{limit}
